import{_ as a,o as e,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Agent 与 Workflow","description":"从控制权、确定性、状态和失败方式区分 Agent 与 Workflow，并给出可复用的架构选择方法。","frontmatter":{"title":"Agent 与 Workflow","description":"从控制权、确定性、状态和失败方式区分 Agent 与 Workflow，并给出可复用的架构选择方法。","framework":"通用 Agent 架构 / LangChain v1","version":"Python 3.12 / LangChain 1.3.x","verified_at":"2026-07-29","source":["https://docs.langchain.com/oss/python/langchain/agents","https://docs.langchain.com/oss/python/langchain/middleware/overview"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/agent/agent-langchain/agent-vs-workflow.md","filePath":"py-agent/agent/agent-langchain/agent-vs-workflow.md","lastUpdated":1785311412000}'),o={name:"py-agent/agent/agent-langchain/agent-vs-workflow.md"};function l(d,t,s,i,h,p){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="agent-与-workflow" tabindex="-1">Agent 与 Workflow <a class="header-anchor" href="#agent-与-workflow" aria-label="Permalink to &quot;Agent 与 Workflow&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 和 Workflow 都能把模型、工具与业务步骤连接起来，但二者把“下一步做什么”的决定权交给了不同对象。理解这条边界，比记住某个框架的类名更重要。</p><h2 id="_1-核心区别-谁决定下一步" tabindex="-1">1. 核心区别：谁决定下一步 <a class="header-anchor" href="#_1-核心区别-谁决定下一步" aria-label="Permalink to &quot;1. 核心区别：谁决定下一步&quot;">​</a></h2><p><strong>Workflow</strong> 由程序预先定义控制流。节点、分支、循环与终止条件来自代码或配置，模型只能为某个节点提供结果。</p><p><strong>Agent</strong> 把一部分控制权交给模型。模型根据消息、工具描述和工具结果，动态决定调用哪个工具、使用什么参数，以及何时结束。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Workflow: 输入 -&gt; 程序选择步骤 -&gt; 执行 -&gt; 程序判断下一步</span></span>
<span class="line"><span>Agent:    输入 -&gt; 模型选择动作 -&gt; 执行工具 -&gt; 结果返回模型 -&gt; 模型再选择</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>“使用了大模型”不等于 Agent。固定执行“分类 -&gt; 检索 -&gt; 生成”的程序仍然是 Workflow。</p><h2 id="_2-workflow-的组成模型" tabindex="-1">2. Workflow 的组成模型 <a class="header-anchor" href="#_2-workflow-的组成模型" aria-label="Permalink to &quot;2. Workflow 的组成模型&quot;">​</a></h2><p>一个 Workflow 通常由五类对象组成：</p><table tabindex="0"><thead><tr><th>对象</th><th>职责</th></tr></thead><tbody><tr><td>State</td><td>保存流程当前事实，例如订单状态、累计结果和尝试次数</td></tr><tr><td>Step / Node</td><td>执行一个边界清楚的处理步骤</td></tr><tr><td>Edge / Route</td><td>根据确定规则选择下一步</td></tr><tr><td>Policy</td><td>定义超时、重试、权限和预算</td></tr><tr><td>Terminal State</td><td>声明成功、拒绝、失败或人工接管等终态</td></tr></tbody></table><p>Workflow 的优势不是“完全不会变化”，而是变化范围可以预先枚举、测试和审计。</p><h3 id="_2-1-适合-workflow-的问题" tabindex="-1">2.1 适合 Workflow 的问题 <a class="header-anchor" href="#_2-1-适合-workflow-的问题" aria-label="Permalink to &quot;2.1 适合 Workflow 的问题&quot;">​</a></h3><ul><li>法规、财务或审批流程要求路径可证明；</li><li>步骤有限，分支可以穷举；</li><li>外部操作有明显副作用；</li><li>失败后必须从确定位置恢复；</li><li>需要稳定延迟和成本上限。</li></ul><h2 id="_3-agent-的组成模型" tabindex="-1">3. Agent 的组成模型 <a class="header-anchor" href="#_3-agent-的组成模型" aria-label="Permalink to &quot;3. Agent 的组成模型&quot;">​</a></h2><p>Agent 至少包含以下部分：</p><table tabindex="0"><thead><tr><th>对象</th><th>职责</th></tr></thead><tbody><tr><td>Model</td><td>根据当前上下文生成工具调用或最终回答</td></tr><tr><td>Instructions</td><td>规定目标、约束和输出原则</td></tr><tr><td>Tools</td><td>描述 Agent 可以请求的外部能力</td></tr><tr><td>State</td><td>保存消息和本轮执行数据</td></tr><tr><td>Runtime</td><td>执行模型调用、工具调用和中间件</td></tr><tr><td>Stop Policy</td><td>限制步数、时间、成本和高风险动作</td></tr></tbody></table><p>Agent 的价值来自<strong>有限范围内的动态决策</strong>，不是来自“让模型自由发挥”。工具集合、权限、预算和终止条件仍应由程序控制。</p><h3 id="_3-1-适合-agent-的问题" tabindex="-1">3.1 适合 Agent 的问题 <a class="header-anchor" href="#_3-1-适合-agent-的问题" aria-label="Permalink to &quot;3.1 适合 Agent 的问题&quot;">​</a></h3><ul><li>用户目标开放，无法事先枚举所有合理步骤；</li><li>工具选择依赖自然语言语义；</li><li>同一目标可能需要不同数量的步骤；</li><li>允许模型在受控范围内探索和修正；</li><li>结果可通过验证器、人工或后续流程检查。</li></ul><h2 id="_4-agent-与-workflow-不是二选一" tabindex="-1">4. Agent 与 Workflow 不是二选一 <a class="header-anchor" href="#_4-agent-与-workflow-不是二选一" aria-label="Permalink to &quot;4. Agent 与 Workflow 不是二选一&quot;">​</a></h2><p>实际系统通常位于一条连续谱上：</p><table tabindex="0"><thead><tr><th>方案</th><th>控制权</th><th>典型例子</th></tr></thead><tbody><tr><td>普通函数</td><td>全部在代码</td><td>格式转换、精确计算</td></tr><tr><td>固定 Workflow</td><td>路径由代码定义</td><td>审批、数据处理流水线</td></tr><tr><td>模型增强 Workflow</td><td>路径固定，节点使用模型</td><td>分类、摘要、结构化抽取</td></tr><tr><td>受控 Agent</td><td>模型选择有限工具，程序限制边界</td><td>客服查询、研究助手</td></tr><tr><td>多 Agent / 动态 Workflow</td><td>多个决策者协作</td><td>跨领域研究、复杂任务分解</td></tr></tbody></table><p>优先选择左侧更简单的方案。只有当固定路径无法合理覆盖需求时，才增加模型控制权。</p><h2 id="_5-五个选择标准" tabindex="-1">5. 五个选择标准 <a class="header-anchor" href="#_5-五个选择标准" aria-label="Permalink to &quot;5. 五个选择标准&quot;">​</a></h2><h3 id="_5-1-路径是否可枚举" tabindex="-1">5.1 路径是否可枚举 <a class="header-anchor" href="#_5-1-路径是否可枚举" aria-label="Permalink to &quot;5.1 路径是否可枚举&quot;">​</a></h3><p>能画出完整状态图并穷举分支时，Workflow 更合适。路径主要取决于自然语言目标和运行结果时，Agent 才有优势。</p><h3 id="_5-2-错误代价是否可接受" tabindex="-1">5.2 错误代价是否可接受 <a class="header-anchor" href="#_5-2-错误代价是否可接受" aria-label="Permalink to &quot;5.2 错误代价是否可接受&quot;">​</a></h3><p>读取公开信息和删除生产数据不是同一级风险。高风险动作即使由 Agent 提议，也应通过确定性校验或人工审批。</p><h3 id="_5-3-是否需要可恢复执行" tabindex="-1">5.3 是否需要可恢复执行 <a class="header-anchor" href="#_5-3-是否需要可恢复执行" aria-label="Permalink to &quot;5.3 是否需要可恢复执行&quot;">​</a></h3><p>长时间运行、人工暂停和外部副作用通常需要显式 Workflow 状态。Agent 可以作为其中一个节点，而不必控制整个拓扑。</p><h3 id="_5-4-延迟和成本是否有硬上限" tabindex="-1">5.4 延迟和成本是否有硬上限 <a class="header-anchor" href="#_5-4-延迟和成本是否有硬上限" aria-label="Permalink to &quot;5.4 延迟和成本是否有硬上限&quot;">​</a></h3><p>固定 Workflow 更容易估算调用次数。Agent 必须增加最大步骤、总超时、Token 预算和无进展检测。</p><h3 id="_5-5-结果能否验证" tabindex="-1">5.5 结果能否验证 <a class="header-anchor" href="#_5-5-结果能否验证" aria-label="Permalink to &quot;5.5 结果能否验证&quot;">​</a></h3><p>无法验证的开放任务不适合直接扩大 Agent 自主性。至少要有 Schema、事实来源、业务规则、测试样例或人工复核中的一种。</p><h2 id="_6-推荐组合-workflow-管边界-agent-解不确定性" tabindex="-1">6. 推荐组合：Workflow 管边界，Agent 解不确定性 <a class="header-anchor" href="#_6-推荐组合-workflow-管边界-agent-解不确定性" aria-label="Permalink to &quot;6. 推荐组合：Workflow 管边界，Agent 解不确定性&quot;">​</a></h2><p>以退款处理为例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接收申请</span></span>
<span class="line"><span>  -&gt; 程序校验身份与订单</span></span>
<span class="line"><span>  -&gt; Agent 汇总原因并建议处理方式</span></span>
<span class="line"><span>  -&gt; 程序校验金额和政策</span></span>
<span class="line"><span>  -&gt; 人工批准高风险退款</span></span>
<span class="line"><span>  -&gt; 程序执行退款并记录审计</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Agent 负责解释模糊材料，Workflow 负责权限、金额、审批和副作用。这样的分工比让 Agent 直接拥有退款工具更容易测试。</p><h2 id="_7-两类系统的失败方式" tabindex="-1">7. 两类系统的失败方式 <a class="header-anchor" href="#_7-两类系统的失败方式" aria-label="Permalink to &quot;7. 两类系统的失败方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>失败</th><th>Workflow</th><th>Agent</th></tr></thead><tbody><tr><td>路径错误</td><td>条件或状态建模错误</td><td>模型选择了错误动作</td></tr><tr><td>参数错误</td><td>程序转换错误</td><td>模型生成了无效参数</td></tr><tr><td>无限执行</td><td>循环条件错误</td><td>工具循环或反复改写</td></tr><tr><td>权限越界</td><td>服务端授权缺失</td><td>工具暴露过多或上下文伪造</td></tr><tr><td>不可复现</td><td>外部依赖变化</td><td>还叠加模型随机性与版本变化</td></tr></tbody></table><p>因此，Agent 并不会消除 Workflow 的工程问题，反而增加了模型决策这一层不确定性。</p><h2 id="_8-决策清单" tabindex="-1">8. 决策清单 <a class="header-anchor" href="#_8-决策清单" aria-label="Permalink to &quot;8. 决策清单&quot;">​</a></h2><p>在引入 Agent 前逐项回答：</p><ol><li>固定函数或 Workflow 为什么不够？</li><li>模型可以决定哪些动作，不能决定哪些动作？</li><li>哪些工具只读，哪些有副作用？</li><li>最大步骤、超时和成本是多少？</li><li>什么条件算成功、拒绝、失败或需要人工？</li><li>如何记录每次模型和工具决策？</li><li>用什么测试证明 Agent 优于更简单的基线？</li></ol><h2 id="_9-小结" tabindex="-1">9. 小结 <a class="header-anchor" href="#_9-小结" aria-label="Permalink to &quot;9. 小结&quot;">​</a></h2><p>Workflow 的核心是<strong>显式控制流</strong>，Agent 的核心是<strong>受约束的动态决策</strong>。选择时不要问“能不能用 Agent”，而应问“哪些不确定性值得交给模型，以及程序如何约束和验证这些决定”。</p>`,47)])])}const b=a(o,[["render",l]]);export{c as __pageData,b as default};
